  padding: 16px 18px;
  background: transparent;
  border-right: 1px solid rgba(255,255,255,0.2);
}
.mn-context-card:last-child {
  border-right: none;
}
.mn-context-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: rgba(255,255,255,0.75);
  margin: 0 0 6px;
}
.mn-context-value {
  font-size: 15px;
  font-weight: 700;
  color: #fff;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Header semaine ── */
.weekRangeTitle {
  font-size: 1.35rem;
  font-weight: 700;
  color: rgb(var(--v-theme-text));
  letter-spacing: -0.01em;
}

.weekSubtitle {
  font-size: 0.85rem;
  color: rgba(var(--v-theme-text), 0.6);
