<script>
import { ref, computed, onMounted, watch, nextTick } from "vue";
import { useRouter } from "vue-router";
import { useAuthStore } from "@/store/auth_store";
import { getUserRecipes } from "@/service/recipe_service";
import { getUserWeeklyMenu } from "@/service/menu_storage_service";
import { getUserShoppingLists } from "@/service/shopping_list_service";
import { getBaseMetabolicRate, getDailyNeeds, getTargetCalories, calculateMacros } from "@/service/health_service";
import { doc, setDoc, getDoc } from "firebase/firestore";
import { db } from "@/firebase";

const DAY_SHORT = ['Lun.','Mar.','Mer.','Jeu.','Ven.','Sam.','Dim.'];
const DAY_FULL  = ['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];
const ARC_TOTAL = 220; // arc length for our SVG path

export default {
  name: "HomeBlock",
  setup() {
    const authStore = useAuthStore();
    const router = useRouter();
    const recipes = ref([]);
    const isLoadingRecipes = ref(false);
    const isLoadingMenu = ref(false);
    const isLoadingCourses = ref(false);
    const weeklyMenu = ref(null);
    const shoppingLists = ref({});
    const coursesView = ref('day');
    const selectedDayIndex = ref(0);
    const editingWeight = ref(false);
    const newWeight = ref(null);
    const weightInputRef = ref(null);
    const weightSnack = ref({ show: false, text: '', color: 'success' });

    const randomRecipe = ref(null);
    const isSpinning = ref(false);
    const baseRecipes = ref([]);
    const isLoadingBaseRecipes = ref(false);
    const randomMealFilter = ref('all');
    const randomRecipeDialog = ref(false);
    const addingToMyRecipes = ref(false);
    const addedToMyRecipes = ref(false);

    const mealFilters = [
      { value: 'all',       label: 'Tout',      emoji: '🍽️',  categories: [] },
      { value: 'breakfast', label: 'Petit-déj', emoji: '🌅',  categories: ['Breakfast'] },
      { value: 'snack',     label: 'Collation', emoji: '🍎',  categories: ['Snack', 'Snacks'] },
      { value: 'meal',      label: 'Plat',      emoji: '🍲',  categories: ['Meal', 'Starter'] },
      { value: 'dessert',   label: 'Dessert',   emoji: '🍰',  categories: ['Dessert'] },
    ];

    const filteredBaseRecipes = computed(() => {
      const filter = mealFilters.find(f => f.value === randomMealFilter.value);
      if (!filter || !filter.categories.length) return baseRecipes.value;
      return baseRecipes.value.filter(r => filter.categories.includes(r.category));
    });

    const getBaseRecipeImage = (item) => item && (item.imageUrl || item.url || item.image) || '';

    const pickRandom = () => {
      const pool = filteredBaseRecipes.value;
      if (!pool.length) return;
      isSpinning.value = true;
      randomRecipe.value = null;
      addedToMyRecipes.value = false;
      setTimeout(() => {
        const idx = Math.floor(Math.random() * pool.length);
        randomRecipe.value = pool[idx];
        isSpinning.value = false;
      }, 700);
    };

    const openRandomRecipeDialog = () => {
      if (randomRecipe.value) {
        addedToMyRecipes.value = false;
        randomRecipeDialog.value = true;
      }
    };

    const addRandomToMyRecipes = async () => {
      if (!randomRecipe.value || !authStore.userid) return;
      addingToMyRecipes.value = true;
      try {
        const { addBaseRecipeToUser } = await import('@/service/base_recipe_service');
        const result = await addBaseRecipeToUser(authStore.userid, randomRecipe.value, randomRecipe.value.id);
        addedToMyRecipes.value = true;
        if (result.existed) {
          // déjà dans la collection, on le signale quand même positivement
        }
      } catch (e) {
        console.error(e);
      } finally {
        addingToMyRecipes.value = false;
      }
    };

    const today = new Date();
    const dow = today.getDay();
    const mondayOffset = dow === 0 ? -6 : 1 - dow;
    const monday = new Date(today);
    monday.setDate(today.getDate() + mondayOffset);

    const weekDays = computed(() => Array.from({ length: 7 }, (_, i) => {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      const months = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
      return { short: DAY_SHORT[i], full: DAY_FULL[i] + ' ' + d.getDate() + ' ' + months[d.getMonth()], num: d.getDate(), date: d };
    }));

    const todayIndex = computed(() => {
      const tn = today.getDate(), tm = today.getMonth();
      return weekDays.value.findIndex(d => d.date.getDate() === tn && d.date.getMonth() === tm);
    });

    const toNumber = (v) => { const n = Number(v); return Number.isFinite(n) ? n : null; };

    const actualWeight = computed(() => toNumber(authStore.userInfos?.actualWeight));
    const targetWeight = computed(() => toNumber(authStore.userInfos?.targetWeight));
    const originalWeight = computed(() => toNumber(authStore.userInfos?.originalWeight));
    const displayTargetWeight = computed(() => targetWeight.value ?? actualWeight.value);

    // Arc de cercle poids
    const weightProgress = computed(() => {
      const w = actualWeight.value, t = targetWeight.value, o = originalWeight.value || w;
      if (!w || !t || !o) return 0;
      const total = Math.abs(t - o);
      if (total === 0) return 100;
      return Math.min(100, Math.round((Math.abs(w - o) / total) * 100));
    });

    const arcLength = computed(() => ARC_TOTAL);
    const arcDashOffset = computed(() => {
      const w = actualWeight.value, t = targetWeight.value, o = originalWeight.value || w;
      if (!w || !t || !o) return ARC_TOTAL;
      const totalDelta = Math.abs(t - o);
      if (totalDelta === 0) return 0;
      const done = Math.abs(w - o);
      const progress = Math.min(1, done / totalDelta);
      return ARC_TOTAL - (ARC_TOTAL * progress);
    });

    const targetCalories = computed(() => {
      const u = authStore.userInfos;
      if (!u) return null;
      const w = toNumber(u.actualWeight), h = toNumber(u.actualSize), nap = toNumber(u.NAP) || 1.4;
      if (!w || !h) return null;
      return getTargetCalories(getDailyNeeds(getBaseMetabolicRate(u.age, h, w, u.sex), nap), u.weightObjective);
    });

    const macros = computed(() => {
      const u = authStore.userInfos;
      if (!u || !targetCalories.value) return null;
      const w = toNumber(u.actualWeight);
      if (!w) return null;
      return calculateMacros(w, u.activityLevel, u.weightObjective, targetCalories.value);
    });

    // Menus planifiés
    const menusTotal = computed(() => {
      const w = actualWeight.value, t = targetWeight.value;
      if (!w || !t) return 20;
      const delta = Math.abs(t - w);
      const months = Math.ceil(delta / 1.5) || 1;
      return months * 4;
    });
    const menusCompleted = computed(() => menusSaved.value ? 1 : 0);

    const MEAL_ORDER = ['breakfast', 'lunch', 'snack', 'dinner'];
    const orderedMealKeys = (menu) => {
      if (!menu) return [];
      const keys = Object.keys(menu);
      return [...MEAL_ORDER.filter(k => keys.includes(k)), ...keys.filter(k => !MEAL_ORDER.includes(k))];
    };

    const TAG_COLORS = [
      { bg: 'rgba(117,83,252,0.1)', color: '#7553FC' },
      { bg: 'rgba(34,197,94,0.1)', color: '#16a34a' },
      { bg: 'rgba(249,115,22,0.1)', color: '#ea6c0b' },
      { bg: 'rgba(236,72,153,0.1)', color: '#db2777' },
      { bg: 'rgba(14,165,233,0.1)', color: '#0284c7' },
      { bg: 'rgba(234,179,8,0.1)', color: '#ca8a04' },
    ];

    const profileTags = computed(() => {
      const u = authStore.userInfos;
      if (!u) return [];
      const tags = [];

      // 1. Objectif principal
      if (u.weightObjective) {
        const map = { loseWeight: 'Perte de poids', gainWeight: 'Prise de masse', maintainWeight: 'Maintien' };
        if (map[u.weightObjective]) tags.push(map[u.weightObjective]);
      }

      // 2. Régime alimentaire (string ou tableau)
      const dietMap = { vegan: 'Végan', vegetarian: 'Végétarien', flexitarian: 'Flexitarien', pescatarian: 'Pescatarien', halal: 'Halal', kosher: 'Casher' };
      const diets = Array.isArray(u.diet) ? u.diet : (u.diet ? [u.diet] : []);
      diets.filter(d => d && d !== 'none' && d !== 'omnivore').forEach(d => tags.push(dietMap[d] || d));

      // 3. Intolérances
      if (Array.isArray(u.intolerances)) u.intolerances.filter(i => i && i !== 'none' && i !== 'preferNotToAnswer').forEach(i => {
        const map = { gluten: 'Sans gluten', lactose: 'Sans lactose', nuts: 'Sans noix', eggs: 'Sans œufs', soy: 'Sans soja', fish: 'Sans poisson' };
        tags.push(map[i] || i);
      });

      // 4. Allergies
      if (Array.isArray(u.allergies)) u.allergies.filter(a => a && a !== 'none' && a !== 'preferNotToAnswer').forEach(a => {
        const map = { peanuts: 'Cacahuètes', nuts: 'Noix', fish: 'Poisson', eggs: 'Œufs', shellfish: 'Crustacés', milk: 'Lait', wheat: 'Blé', soy: 'Soja' };
        tags.push(map[a] || a);
      });

      // 5. Conditions médicales
      if (Array.isArray(u.medicalConditions)) u.medicalConditions.filter(c => c && c !== 'none' && c !== 'preferNotToAnswer').forEach(c => {
        const map = {
          diabetes: 'Diabète', hypertension: 'Hypertension', cholesterol: 'Cholestérol',
          ibs: 'Côlon irritable', celiac: 'Cœliaque', anxiety: 'Anxiété', depression: 'Dépression',
          crohndisease: 'Crohn', thyroid: 'Thyroïde', pcos: 'SOPK', endometriosis: 'Endométriose',
          arthritis: 'Arthrite', gerd: 'RGO',
        };
        const key = c.toLowerCase().replace(/[^a-z]/g, '');
        const translated = map[key] || (key.includes('bilia') || key.includes('vesicul') ? 'Vésicule biliaire' : c);
        tags.push(translated);
      });

      return tags.slice(0, 8).map((label, i) => ({ label, ...TAG_COLORS[i % TAG_COLORS.length] }));
    });

    const caloriesSlide = ref(0);
    const macroIdx = ref(0);
    const macroItems = computed(() => [
      { label: 'Protéines', val: macros.value ? Math.round(macros.value.proteinNeeds) : '—' },
      { label: 'Glucides',  val: macros.value ? Math.round(macros.value.carbNeeds)    : '—' },
      { label: 'Lipides',   val: macros.value ? Math.round(macros.value.fatNeeds)     : '—' },
      { label: 'Fibres',    val: 30 },
    ]);

    const formatWeight = (v) => v == null ? '--' : `${v.toFixed(1)} kg`;

    const formatQty = (item) => {
      const g = item.grams || 0;
      if (g >= 1000) return `${(g / 1000).toFixed(1)} kg`;
      if (g > 0) return `${g}g`;
      return item.quantity ? `${item.quantity} ${item.unit || ''}`.trim() : '';
    };

    const startEditWeight = async () => {
      newWeight.value = actualWeight.value;
      editingWeight.value = true;
      await nextTick();
      weightInputRef.value?.focus();
    };

    const saveWeight = async () => {
      if (!editingWeight.value) return;
      editingWeight.value = false;
      const w = newWeight.value;
      if (!w || w === actualWeight.value || w < 20 || w > 300) return;
      try {
        const docRef = doc(db, 'User', authStore.userid);
        const snap = await getDoc(docRef);
        await setDoc(docRef, { ...(snap.exists() ? snap.data() : {}), actualWeight: w }, { merge: true });
        if (authStore.userInfos) authStore.userInfos.actualWeight = w;
        weightSnack.value = { show: true, text: `Poids mis à jour : ${w} kg ✅`, color: 'success' };
      } catch (e) {
        weightSnack.value = { show: true, text: 'Erreur lors de la mise à jour', color: 'error' };
      }
    };

    const nextMeal = computed(() => {
      if (!weeklyMenu.value?.daily) return null;
      const todayIdx = todayIndex.value >= 0 ? todayIndex.value : 0;
      const dayMenu = weeklyMenu.value.daily[todayIdx]?.menu;
      if (!dayMenu) return null;
      const now = new Date();
      const hour = now.getHours();
      const min = now.getMinutes();
      const timeInMin = hour * 60 + min;
      // Petit-déj: <10h et ≥22h | Déjeuner: 10h-13h30 | Collation: 13h30-17h | Dîner: 17h-22h
      let order;
      if (timeInMin < 600 || timeInMin >= 1320) {
        order = ['breakfast','lunch','snack','dinner'];
      } else if (timeInMin < 810) {
        order = ['lunch','snack','dinner','breakfast'];
      } else if (timeInMin < 1020) {
        order = ['snack','dinner','breakfast','lunch'];
      } else {
        order = ['dinner','breakfast','lunch','snack'];
      }
      for (const mealType of order) {
        const meals = dayMenu[mealType];
        if (meals && meals.length) return { mealType, recipe: meals[0] };
      }
      // fallback: first meal
      const first = Object.values(dayMenu)[0];
      return first && first.length ? { mealType: Object.keys(dayMenu)[0], recipe: first[0] } : null;
    });

    const menusSaved = computed(() => !!(weeklyMenu.value && weeklyMenu.value.daily && weeklyMenu.value.daily.length));
    const selectedDayMenu = computed(() => weeklyMenu.value && weeklyMenu.value.daily ? weeklyMenu.value.daily[selectedDayIndex.value] && weeklyMenu.value.daily[selectedDayIndex.value].menu || null : null);
    const selectedDayTotals = computed(() => weeklyMenu.value && weeklyMenu.value.daily ? Math.round((weeklyMenu.value.daily[selectedDayIndex.value] && weeklyMenu.value.daily[selectedDayIndex.value].totals && weeklyMenu.value.daily[selectedDayIndex.value].totals.kcal) || 0) : 0);

    const shoppingItems = computed(() => {
      const lists = Object.values(shoppingLists.value);
      if (!lists.length) return [];
      const menuList = lists.find(l => l.generatedFromMenu);
      if (!menuList) return [];

      if (coursesView.value === 'week') {
        return menuList.items || [];
      }

      // Vue "Jour" : recalculer les ingrédients du jour sélectionné
      const dayMenu = selectedDayMenu.value;
      if (!dayMenu) return [];
      const ingredientsMap = {};
      for (const meals of Object.values(dayMenu)) {
        for (const recipe of meals) {
          if (!recipe.ingredients) continue;
          for (const ing of recipe.ingredients) {
            const name = ing.name || ing.productName || '';
            if (!name) continue;
            const key = name.toLowerCase().trim();
            if (ingredientsMap[key]) {
              ingredientsMap[key].grams = (ingredientsMap[key].grams || 0) + (ing.grams || 0);
            } else {
              ingredientsMap[key] = { name, grams: ing.grams || 0, quantity: '1', checked: false };
            }
          }
        }
      }
      return Object.values(ingredientsMap);
    });

    const toTimestamp = (raw) => {
      if (!raw) return null;
      if (typeof raw === 'number') return raw;
      if (typeof raw === 'string') { const p = Date.parse(raw); return Number.isNaN(p) ? null : p; }
      if (typeof raw === 'object' && raw.seconds) return raw.seconds * 1000;
      return null;
    };

    const selectLatest = (items, fields) => [...items.map((item, index) => {
      const rawDate = fields.map(f => item && item[f]).find(v => v !== undefined && v !== null);
      return { item, index, ts: toTimestamp(rawDate) };
    })].sort((a, b) => { if (a.ts && b.ts) return b.ts - a.ts; if (a.ts) return -1; if (b.ts) return 1; return b.index - a.index; }).slice(0, 5).map(e => e.item);

    const latestRecipes = computed(() => selectLatest(recipes.value, ['createdAt', 'updatedAt']));
    const getRecipeImage = (item) => item && (item.url || item.image || item.imageUrl) || '';

    const categoryMap = { 'Meal': 'Plat', 'Starter': 'Entrée', 'Dessert': 'Dessert', 'Breakfast': 'Petit-déjeuner', 'Snacks': 'Collation', 'Snack': 'Collation' };
    const translateCategory = (cat) => cat ? (categoryMap[cat] || cat) : 'Sans catégorie';

