              shoppingLists.value = await getUserShoppingLists(authStore.userid);
            }
          }
        } catch(e){console.error(e);} finally { isLoadingCourses.value = false; }
      }, { immediate: true });
    });

    const showAddItem = ref(false);
    const newItemName = ref('');

    const addCourseItem = async () => {
      const name = newItemName.value.trim();
      if (!name) return;
      const lists = Object.values(shoppingLists.value);
      const menuList = lists.find(l => l.generatedFromMenu);
      const target = menuList || [...lists].sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0))[0];
      if (!target || !target.id) return;
      const items = [...(target.items || []), { name, grams: 0, quantity: '1', checked: false }];
      try {
        const { updateShoppingList } = await import('@/service/shopping_list_service');
        await updateShoppingList(authStore.userid, target.id, { ...target, items });
        shoppingLists.value = { ...shoppingLists.value, [target.id]: { ...target, items } };
        newItemName.value = '';
        showAddItem.value = false;
      } catch(e) { console.error(e); }
    };

